  $ramp=@(); foreach($light in @(15,26,38,49,61,72,84,95)){$ramp+=('oklch({0}% {1} {2})' -f $light,$c.ToString('0.0000',[cultureinfo]::InvariantCulture),$h.ToString('0.0',[cultureinfo]::InvariantCulture))}
  $role=if($key -in @('green','nav')){'primary'}elseif($key -match 'amber|blue|green-status'){'secondary'}else{'neutral'}
  $colorMeta[$key]=@{role=$role;displayName=(Get-Culture).TextInfo.ToTitleCase($key.Replace('-',' '));tonalRamp=$ramp}
}
