parsed_cmd.cmd:
$doc = Get-Content -Raw DESIGN.md; $source = Get-Content -Raw frontend/src/styles.css
$colors = [ordered]@{}; $colorBlock = ($doc -split 'typography:')[0] -split 'colors:' | Select-Object -Last 1
foreach($match in [regex]::Matches($colorBlock,'(?m)^  ([a-z-]+): "(#[a-f0-9]+)"')) { $colors[$match.Groups[1].Value]=$match.Groups[2].Value }
$colorMeta=[ordered]@{}
foreach($key in $colors.Keys) {
  $hex=$colors[$key]; $v=@(); for($i=1;$i -lt 7;$i+=2){$s=[Convert]::ToInt32($hex.Substring($i,2),16)/255; $v+= $(if($s -le .04045){$s/12.92}else{[Math]::Pow(($s+.055)/1.055,2.4)})}
  $l=[Math]::Pow(.4122214708*$v[0]+.5363325363*$v[1]+.0514459929*$v[2],1/3); $m=[Math]::Pow(.2119034982*$v[0]+.6806995451*$v[1]+.1073969566*$v[2],1/3); $s=[Math]::Pow(.0883024619*$v[0]+.2817188376*$v[1]+.6299787005*$v[2],1/3)
  $a=1.9779984951*$l-2.428592205*$m+.4505937099*$s; $b=.0259040371*$l+.7827717662*$m-.808675766*$s; $c=[Math]::Sqrt($a*$a+$b*$b); $h=([Math]::Atan2($b,$a)*180/[Math]::PI+360)%360
  $ramp=@(); foreach($light in @(15,26,38,49,61,72,84,95)){$ramp+=('oklch({0}% {1} {2})' -f $light,$c.ToString('0.0000',[cultureinfo]::InvariantCulture),$h.ToString('0.0',[cultureinfo]::InvariantCulture))}
  $role=if($key -in @('green','nav')){'primary'}elseif($key -match 'amber|blue|green-status'){'secondary'}else{'neutral'}
  $colorMeta[$key]=@{role=$role;displayName=(Get-Culture).TextInfo.ToTitleCase($key.Replace('-',' '));tonalRamp=$ramp}
}
