 @{name='Labeled Field';kind='input';refersTo='field';description='Review and claim information fields.';html='<label class="ds-field-label">Reviewer name<input class="ds-field" placeholder="Your name"></label>';css=".ds-field-label{${base}display:flex;flex-direction:column;gap:7px;color:#506f3c;font-weight:500}.ds-field{${base}border:1px solid #c9d7bc;border-radius:5px;background:#fff;padding:11px;color:#2d532c;caret-color:var(--green,#246c54)}.ds-field::placeholder{color:#69786c;opacity:1}.ds-field:focus{outline:2px solid #43856a;outline-offset:1px}"},
 @{name='Selected Navigation';kind='nav';refersTo='navigation';description='Current workspace destination.';html='<nav class="ds-nav"><button class="ds-nav-item" aria-current="page">Invoice ledger</button></nav>';css=".ds-nav{background:var(--nav,#173b34);padding:17px}.ds-nav-item{font-family:DM Sans,sans-serif;font-size:12px;border:0;border-radius:7px;padding:13px 10px;width:100%;text-align:left;color:#e8f1d8;background:#375a4a;cursor:pointer}.ds-nav-item:hover{background:#2c4d42}.ds-nav-item$focus"},
 @{name='Neutral Status';kind='chip';refersTo='badge-neutral';description='Plain descriptive status.';html='<span class="ds-badge">Synthetic records</span>';css='.ds-badge{display:inline-flex;align-items:center;justify-content:center;gap:4px;border-radius:4px;padding:4px 7px;font-family:DM Sans,sans-serif;font-size:9px;line-height:1.5;font-weight:500;white-space:nowrap;color:#5b7153;background:#edf2e7}'},
 @{name='Record Panel';kind='card';refersTo='panel';description='Bounded record details and financial workspace.';html='<section class="ds-panel"><header class="ds-panel-heading"><h2>Selected invoice</h2><p>Follow the linked supporting records.</p></header></section>';css='.ds-panel{background:#fff;border:1px solid var(--border,#dce3d9);border-radius:var(--radius,12px);overflow:hidden;min-width:0;color:#23382f;font-family:DM Sans,sans-serif}.ds-panel-heading{padding:20px}.ds-panel-heading h2{margin:0;font-size:17px;font-weight:600;line-height:1.4}.ds-panel-heading p{margin:5px 0 0;font-size:11px;line-height:1.65;color:#536747}'},
 @{name='Source Paper';kind='custom';refersTo='source-paper';description='Readable source excerpt with numbered lines.';html='<div class="ds-stage"><article class="ds-paper"><h3>Supporting record</h3><div class="ds-line"><span>1</span><p>Synthetic source excerpt</p></div></article></div>';css='.ds-stage{background:#e6eae2;padding:21px}.ds-paper{background:#fff;padding:27px 24px;box-shadow:0 8px 21px #1d382715}.ds-paper h3{font-family:Lora,serif;font-size:18px;font-weight:500;line-height:1.5;color:#2c4d34;margin:0 0 23px;border-bottom:1px solid #bed0ac;padding-bottom:25px}.ds-line{display:flex;align-items:flex-start;gap:13px;font-family:DM Sans,sans-serif}.ds-line span{width:14px;color:#7c8e6e;font-size:9px;font-variant-numeric:tabular-nums;padding-top:3px}.ds-line p{margin:0;font-size:12px;line-height:1.9;color:#3a573a;white-space:pre-wrap}'}
)
